ExecutorService pool = Executors.newFixedThreadPool(4);

Future<Integer> future = pool.submit(() -> {
    Thread.sleep(500);
    return 42;
});

int resultado = future.get(); // bloquea
pool.shutdown();
pool.awaitTermination(5, TimeUnit.SECONDS);

pool.shutdown();
try {
    if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {
        pool.shutdownNow();
        if (!pool.awaitTermination(3, TimeUnit.SECONDS)) {
            System.err.println("Pool no termino");
        }
    }
} catch (InterruptedException e) {
    pool.shutdownNow();
    Thread.currentThread().interrupt();
}

CompletableFuture.supplyAsync(() -> "hola")
    .thenApply(s -> s.toUpperCase())       // transforma
    .thenApply(s -> s + " MUNDO")          // transforma
    .thenAccept(System.out::println)        // consume: HOLA MUNDO
    .exceptionally(ex -> {
        System.err.println("Error: " + ex.getMessage());
        return null;
    });

